	POWER_TELEPORTATION_SIGIL_L2A_NAME = "奧術回溯",
	LEVEL_255_HISTORY = "宏偉的銀色橡樹對精靈們而言，向來是與自然間聯繫的重要象徵。身為盟友他們對於佛則南的威脅肯定是會出手相助的。\n\n然而半獸人們似乎也加入了佛則南的勢力，更準備在這銀橡樹村中大肆破壞......絕不能讓他們得逞了！",
