	TOWER_ALCHEMIST_4_SKILL_B_1_DESCRIPTION = "召喚一名飲下特殊藥劑，暫時化為巨大怪物的助手。此單位擁有 {b.towers.alchemist.skill_b.soldier.hp[1]} 點生命值，且能造成 {b.towers.alchemist.skill_b.soldier.basic_attack.damage_min[1]}-{b.towers.alchemist.skill_b.soldier.basic_attack.damage_max[1]} 真實傷害。助手離場 {b.towers.alchemist.skill_b.cooldown[1]} 秒後可重新召喚。",
