	LEVEL_262_HISTORY = "前往雲暴寺院的道路不只充滿了陡峭的爬坡和險惡的懸崖......這回更直接引我們進入巨魔的老巢了。\n\n在這裡的戰鬥他們占盡了場地的優勢，務必提高警覺，以防隨時會有 「驚喜」 到來。不要放棄，打起精神上吧！",
