	LEVEL_260_HISTORY = "在巨魔的追擊之下，我們抵達了一處寬敞的石窟。陽光從外側滲漏了進來，灑落在了冰結、廣闊的湖泊之上。\n\n眼前的美景雖然讓人屏息......然而四周散落的眾多屍骨，卻訴說著這裡恐怕是某種怪物的危險巢穴。壓低聲響，趕緊通過此處吧。",
